struct Stream {Handle file;ULONGLONG observed=0,persisted=0;bool eof=false,limited=false;std::string sha256;};
Stream Log(const std::wstring& path){Stream stream;stream.file.Reset(CreateFileW(Win32Path(path).c_str(),GENERIC_READ|GENERIC_WRITE,FILE_SHARE_READ,nullptr,CREATE_NEW,FILE_ATTRIBUTE_NORMAL,nullptr));Check(stream.file.h!=INVALID_HANDLE_VALUE,"log_create");return stream;}
void Drain(HANDLE pipe,Stream& stream,ULONGLONG& total){if(stream.eof)return;for(unsigned turn=0;turn<16;++turn){DWORD available=0;if(!PeekNamedPipe(pipe,nullptr,0,nullptr,&available,nullptr)){Require(GetLastError()==ERROR_BROKEN_PIPE,"log_pipe");stream.eof=true;stream.sha256=Hash(stream.file.h,stream.persisted);return;}if(!available)return;std::array<unsigned char,4096> bytes{};DWORD read=0;Check(ReadFile(pipe,bytes.data(),std::min<DWORD>(available,static_cast<DWORD>(bytes.size())),&read,nullptr),"log_read");stream.observed+=read;const DWORD keep=static_cast<DWORD>(std::min<ULONGLONG>(read,logLimit-total));if(keep){DWORD written=0;Check(WriteFile(stream.file.h,bytes.data(),keep,&written,nullptr)&&written==keep,"log_write");Check(FlushFileBuffers(stream.file.h),"log_flush");stream.persisted+=keep;total+=keep;}if(keep<read)stream.limited=true;}}
std::string StreamJson(const Stream& stream,bool terminal){const std::string coverage=stream.limited?"partial_at_limit":(stream.eof?"complete":(terminal?"incomplete":"open"));return "{\"observedBytes\":"+std::to_string(stream.observed)+",\"persistedBytes\":"+std::to_string(stream.persisted)+",\"eof\":"+B(stream.eof)+",\"coverage\":"+S(coverage)+",\"sha256\":"+(stream.sha256.empty()?"null":S(stream.sha256))+"}";}
