// Each flushed snapshot has its own name. Failed publications remain evidence;
// no later snapshot deletes, truncates, or reuses an unpublished file.
void Publish(const std::wstring& temporary,const std::wstring& target,DWORD flags,const char* operation){
  const auto until=GetTickCount64()+250;DWORD firstError=ERROR_SUCCESS;unsigned attempts=0;const bool status=(flags&MOVEFILE_REPLACE_EXISTING)!=0;
  for(;;){++attempts;if(status)++statusAttempts;if(MoveFileExW(Win32Path(temporary).c_str(),Win32Path(target).c_str(),flags)){if(status){++statusPublished;if(attempts>1)++statusRecovered;}return;}
    const DWORD code=GetLastError();if(firstError==ERROR_SUCCESS)firstError=code;
    if(status){++statusFailures;lastStatusCode=code;lastStatusFailureAt=Now();if(firstStatusCode==ERROR_SUCCESS){firstStatusCode=code;firstStatusFailureAt=lastStatusFailureAt;}}
    const auto now=GetTickCount64();const bool replaceDenied=code==ERROR_ACCESS_DENIED&&status;
    if((code!=ERROR_SHARING_VIOLATION&&code!=ERROR_LOCK_VIOLATION&&!replaceDenied)||now>=until||attempts>=26)throw PublicationFailure(operation,firstError,code,attempts);
    Sleep(static_cast<DWORD>(std::min<ULONGLONG>(10,until-now)));
  }
}
void AtomicStatus(const std::string& text,ULONGLONG sequence){
  Require(text.size()<=65536,"status_size");const auto temporary=recoveryRoot+L"\\status-pending-"+std::to_wstring(sequence)+L".json",target=recoveryRoot+L"\\status.json";
  Stage("status_publish",target);
  {Handle file(CreateFileW(Win32Path(temporary).c_str(),GENERIC_WRITE,FILE_SHARE_READ,nullptr,CREATE_NEW,FILE_ATTRIBUTE_NORMAL,nullptr));PublicationCheck(file.h!=INVALID_HANDLE_VALUE,"status_create");DWORD written=0;
    PublicationCheck(WriteFile(file.h,text.data(),static_cast<DWORD>(text.size()),&written,nullptr)&&written==text.size(),"status_write");PublicationCheck(FlushFileBuffers(file.h),"status_flush");}
  Publish(temporary,target,MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH,"status_replace");
}
